export const knowledge: Knowledge[] = source
  .trim()
  .split("\n")
  .map((line) => {
    const [id, category, title, phrases, answer, steps] = line.split("|");
    return {
      id,
      category,
      title,
      phrases: phrases.split("~"),
      keywords: [
        ...new Set((title + " " + phrases).toLowerCase().match(/[a-z0-9]+/g)),
      ],
      answer,
      steps: steps.split("~"),
      followups: ["Give me the steps", "Make that shorter"],
      related: [],
      reference:
        category === "Product"
          ? "https://github.com/hiyroscript/varek"
          : "https://developer.mozilla.org/en-US/docs/Web",
      reviewed: "2026-10-24",
    };
  });
knowledge.push(...extendedKnowledge);
